 };

 int main(int argc, char *argv[]) {
   PDFDoc *doc;
   GString *fileName;
   GString *ownerPW, *userPW;
   UnicodeMap *uMap;
   Page *page;
   Object info;
   char buf[256];
   double w, h, wISO, hISO;
   FILE *f;
   GString *metadata;
   GBool ok;
   int exitCode;
   int pg, i;
   GBool multiPage;

   exitCode = 99;

   // parse args
   ok = parseArgs(argDesc, &argc, argv);
   if (!ok || argc != 2 || printVersion || printHelp) {
     fprintf(stderr, "pdfinfo version %s\n", xpdfVersion);
     fprintf(stderr, "%s\n", xpdfCopyright);
     if (!printVersion) {
       printUsage("pdfinfo", "<PDF-file>", argDesc);
     }
     goto err0;
   }
   fileName = new GString(argv[1]);

   // read config file
   globalParams = new GlobalParams(cfgFileName);
   if (textEncName[0]) {
     globalParams->setTextEncoding(textEncName);
   }

   // get mapping to output encoding
   if (!(uMap = globalParams->getTextEncoding())) {
     error(-1, "Couldn't get text encoding");
     delete fileName;
     goto err1;
   }

   // open PDF file
   if (ownerPassword[0] != '\001') {
     ownerPW = new GString(ownerPassword);
   } else {
     ownerPW = NULL;
   }
   if (userPassword[0] != '\001') {
     userPW = new GString(userPassword);
   } else {
     userPW = NULL;
   }
   doc = new PDFDoc(fileName, ownerPW, userPW);
   if (userPW) {
     delete userPW;
   }
   if (ownerPW) {
     delete ownerPW;
   }
   if (!doc->isOk()) {
     exitCode = 1;
     goto err2;
   }

   // get page range
   if (firstPage < 1) {
     firstPage = 1;
   }
   if (lastPage == 0) {
     multiPage = gFalse;
     lastPage = 1;
   } else {
     multiPage = gTrue;
   }
   if (lastPage < 1 || lastPage > doc->getNumPages()) {
     lastPage = doc->getNumPages();
   }

   // print doc info
   doc->getDocInfo(&info);
   if (info.isDict()) {
     printInfoString(info.getDict(), "Title",        "Title:          ", uMap);
     printInfoString(info.getDict(), "Subject",      "Subject:        ", uMap);
     printInfoString(info.getDict(), "Keywords",     "Keywords:       ", uMap);
     printInfoString(info.getDict(), "Author",       "Author:         ", uMap);
     printInfoString(info.getDict(), "Creator",      "Creator:        ", uMap);
     printInfoString(info.getDict(), "Producer",     "Producer:       ", uMap);
     printInfoDate(info.getDict(),   "CreationDate", "CreationDate:   ");
     printInfoDate(info.getDict(),   "ModDate",      "ModDate:        ");
   }
   info.free();

   // print tagging info
   printf("Tagged:         %s\n",
 	 doc->getStructTreeRoot()->isDict() ? "yes" : "no");

   // print page count
   printf("Pages:          %d\n", doc->getNumPages());

   // print encryption info
   printf("Encrypted:      ");
   if (doc->isEncrypted()) {
     printf("yes (print:%s copy:%s change:%s addNotes:%s)\n",
 	   doc->okToPrint(gTrue) ? "yes" : "no",
 	   doc->okToCopy(gTrue) ? "yes" : "no",
 	   doc->okToChange(gTrue) ? "yes" : "no",
 	   doc->okToAddNotes(gTrue) ? "yes" : "no");
   } else {
     printf("no\n");
   }

   // print page size
   for (pg = firstPage; pg <= lastPage; ++pg) {
     w = doc->getPageCropWidth(pg);
     h = doc->getPageCropHeight(pg);
     if (multiPage) {
       printf("Page %4d size: %g x %g pts", pg, w, h);
     } else {
       printf("Page size:      %g x %g pts", w, h);
     }
     if ((fabs(w - 612) < 0.1 && fabs(h - 792) < 0.1) ||
 	(fabs(w - 792) < 0.1 && fabs(h - 612) < 0.1)) {
       printf(" (letter)");
     } else {
       hISO = sqrt(sqrt(2.0)) * 7200 / 2.54;
       wISO = hISO / sqrt(2.0);
       for (i = 0; i <= 6; ++i) {
 	if ((fabs(w - wISO) < 1 && fabs(h - hISO) < 1) ||
 	    (fabs(w - hISO) < 1 && fabs(h - wISO) < 1)) {
 	  printf(" (A%d)", i);
 	  break;
 	}
 	hISO = wISO;
 	wISO /= sqrt(2.0);
       }
     }
     printf("\n");
   }

